const cv = String($json.cvText || '').trim();
if (cv.length < 200) {
  throw new Error('لا توجد سيرة ذاتية محفوظة. افتح نموذج الرفع (عقدة CV Upload Form) وارفع ملف PDF أو PNG أولاً.');
}
return [{ json: { cvText: cv } }];

const cfg = $('Config').first().json;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
// prune seen-links older than 30 days
for (const k of Object.keys(store.seen)) { if (now - store.seen[k] > 30 * 86400000) delete store.seen[k]; }

const strip = h => String(h || '')
  .replace(/<[^>]*>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/\s+/g, ' ').trim();
const EMAIL = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const BAD_EMAIL = /(no-?reply|donotreply|example\.png|sentry|wixpress)/i;

const maxAge = Number(cfg.maxAgeDays || 7) * 86400000;
const dup = new Set();
const jobs = [];

for (const it of $input.all()) {
  const j = it.json || {};
  if (j.error || !j.title || !j.link) continue;
  const link = String(j.link).trim();
  if (dup.has(link)) continue;
  dup.add(link);
  const sample = j.__sample === true;
  if (!sample && store.seen[link]) continue;

  const rawContent = String(j['content:encoded'] || j.content || j.description || j.contentSnippet || '');
  const description = strip(rawContent).slice(0, 6000);
  const ts = Date.parse(j.isoDate || j.pubDate || '') || now;
  if (!sample && now - ts > maxAge) continue;

  const text = (j.title + ' ' + description).toLowerCase();
  // hard drop: on-site / hybrid roles that never mention remote
  if (/\b(on-?site|in-?office|hybrid)\b/.test(text) && !/remote|work from home|anywhere/.test(text)) continue;

  const emails = ((rawContent + ' ' + description).match(EMAIL) || []).filter(e => !BAD_EMAIL.test(e));
  let host = '';
  try { host = new URL(link).hostname.replace(/^www\./, ''); } catch (e) {}

  jobs.push({ json: {
    title: strip(j.title),
    company: strip(j.creator || j.author || j['dc:creator'] || ''),
    link, source: host,
    pubDate: new Date(ts).toISOString(),
    categories: Array.isArray(j.categories) ? j.categories : [],
    description,
    emailFound: emails[0] || '',
    _ts: ts
  }});
}

jobs.sort((a, b) => b.json._ts - a.json._ts);
return jobs.slice(0, Number(cfg.maxJobsToEvaluate || 12));

const cfg = $('Config').first().json;
const cv = String($('CV Source').first().json.cvText || '').slice(0, 12000);

const system = `You are a strict, evidence-based technical recruiter and ATS screening engine.
Compare the candidate CV with the job posting and return ONLY a JSON object.

SCORING RULES
- match_score (0-100): based ONLY on evidence in the CV versus the job's stated requirements. Be conservative.
  90+ is allowed only if ALL core required skills, the domain and the seniority level clearly match. Deduct heavily for each missing core requirement. Never assume skills the CV does not state.
- job_quality_score (0-100): clarity of the posting, seriousness of the employer, realistic requirements, compensation transparency, technical depth.
- is_remote: true ONLY if the job is explicitly fully remote. On-site or hybrid => false.
- location_ok: true ONLY if the job is open to worldwide/anywhere candidates, OR explicitly open to at least one of the target regions given by the user (Algeria, Europe/EU/UK, USA, Canada). false if restricted to other regions (e.g. India only, APAC only, LATAM only) or if it demands residence outside the target regions.
- contact_email: an application email address that literally appears in the posting text, else "". Never invent one.

OUTPUT JSON SCHEMA (no markdown, no extra text):
{"match_score": integer, "job_quality_score": integer, "is_remote": boolean, "location_ok": boolean, "contact_email": string, "hard_requirements_missing": [string], "strengths": [string], "reasoning": string, "summary_ar": string}
summary_ar is a 1-2 sentence summary of the job written in Arabic.`;

return $input.all().map(it => {
  const j = it.json;
  const user = `CANDIDATE CV:\n"""\n${cv}\n"""\n\nTARGET REGIONS: ${cfg.targetRegions}\nMINIMUM ACCEPTABLE MATCH: ${cfg.minScore}\n\nJOB POSTING\nTitle: ${j.title}\nCompany/Author: ${j.company}\nSource: ${j.source}\nPublished: ${j.pubDate}\nURL: ${j.link}\nCategories: ${(j.categories || []).join(', ')}\nEmail found in text: ${j.emailFound || 'none'}\nDescription:\n"""\n${j.description}\n"""\n\nReturn ONLY the JSON object.`;
  return { json: { ...j, geminiBody: {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig: { temperature: 0.1, maxOutputTokens: 4096, responseMimeType: 'application/json' }
  }}};
});

const bin = $input.first().binary || {};
const key = Object.keys(bin)[0];
if (!key) throw new Error('لم يصل أي ملف. ارفع CV بصيغة PDF أو PNG.');
const meta = bin[key];
const name = String(meta.fileName || '').toLowerCase();
let mime = meta.mimeType || '';
if (!mime) mime = name.endsWith('.pdf') ? 'application/pdf' : name.endsWith('.png') ? 'image/png' : 'image/jpeg';
if (!['application/pdf', 'image/png', 'image/jpeg', 'image/webp'].includes(mime)) {
  throw new Error('صيغة غير مدعومة (' + mime + '). ارفع PDF أو PNG.');
}
const buf = await this.helpers.getBinaryDataBuffer(0, key);
const data = buf.toString('base64');
return [{ json: { geminiBody: {
  contents: [{ role: 'user', parts: [
    { inlineData: { mimeType: mime, data } },
    { text: 'Transcribe this CV/resume completely into clean plain text. Keep every detail exactly as written (name, contacts, skills, experience, education, languages, projects, dates). Do not summarize, translate, or add anything. Output plain text only, no markdown.' }
  ]}],
  generationConfig: { temperature: 0, maxOutputTokens: 8192 }
}}}];

const r = $input.first().json || {};
if (r.error) {
  const e = r.error;
  const msg = typeof e === 'string' ? e : (e.message || JSON.stringify(e));
  throw new Error('فشل Gemini في قراءة الـ CV: ' + String(msg).slice(0, 400));
}
const parts = (r.candidates && r.candidates[0] && r.candidates[0].content && r.candidates[0].content.parts) || [];
const text = parts.map(p => p.text || '').join('').trim();
if (text.length < 200) {
  throw new Error('تعذّر استخراج نص كافٍ من الملف (finishReason: ' + ((r.candidates && r.candidates[0] && r.candidates[0].finishReason) || 'n/a') + '). جرّب ملفاً أوضح.');
}
// Saved for the scheduled runs (persists when the workflow is Active).
$getWorkflowStaticData('global').cvText = text;
return [{ json: { cvText: text } }];

const cfg = $('Config').first().json;
const jobs = $('Build Eval Prompt').all();
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const EMAIL = /^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/;
const maxAgeDays = Number(cfg.maxAgeDays || 7);
const now = Date.now();
const qualified = [];
let failed = 0, lastErr = '';

$input.all().forEach((r, i) => {
  const idx = (r.pairedItem && r.pairedItem.item !== undefined) ? r.pairedItem.item : i;
  const src = jobs[idx];
  if (!src) return;
  const { geminiBody, _ts, ...job } = src.json;

  let ev = null;
  try {
    const t = (r.json && r.json.candidates && r.json.candidates[0] && r.json.candidates[0].content
      ? r.json.candidates[0].content.parts.map(p => p.text || '').join('') : '');
    ev = JSON.parse(t.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim());
  } catch (e) { ev = null; }
  if (!ev) { // AI failed: do not mark as seen, it will be retried next run
    failed++;
    const e = r.json && r.json.error;
    lastErr = e ? (typeof e === 'string' ? e : (e.message || JSON.stringify(e)))
      : (r.json && r.json.promptFeedback ? 'blocked: ' + JSON.stringify(r.json.promptFeedback) : 'empty/invalid AI response');
    return;
  }

  store.seen[job.link] = now;

  const match = Number(ev.match_score) || 0;
  const quality = Number(ev.job_quality_score) || 0;
  if (!(match >= Number(cfg.minScore || 90) && ev.is_remote === true && ev.location_ok === true)) return;

  const ageDays = Math.max(0, (now - Date.parse(job.pubDate)) / 86400000);
  const recency = Math.max(0, 100 - ageDays * (100 / maxAgeDays));
  const finalScore = Math.round((match * 0.6 + quality * 0.25 + recency * 0.15) * 10) / 10;

  let contactEmail = '';
  if (ev.contact_email && EMAIL.test(String(ev.contact_email).trim()) && job.description.includes(String(ev.contact_email).trim())) {
    contactEmail = String(ev.contact_email).trim();
  } else if (job.emailFound && EMAIL.test(job.emailFound)) {
    contactEmail = job.emailFound;
  }

  qualified.push({ json: {
    ...job, matchScore: match, qualityScore: quality, finalScore, contactEmail,
    strengths: ev.strengths || [], missing: ev.hard_requirements_missing || [],
    reasoning: ev.reasoning || '', summaryAr: ev.summary_ar || ''
  }});
});

if (failed > 0 && failed === $input.all().length) {
  throw new Error('فشلت كل طلبات Gemini (' + failed + '): ' + String(lastErr).slice(0, 500));
}
qualified.sort((a, b) => b.json.finalScore - a.json.finalScore);
return qualified.slice(0, Number(cfg.maxApplicationsPerRun || 3));

const cv = String($('CV Source').first().json.cvText || '').slice(0, 12000);
const cfg = $('Config').first().json;

const system = `You write job-application cover letters for the candidate whose CV is provided.
RULES
- Use ONLY facts that appear in the CV. Never invent employers, degrees, numbers, certifications or tools.
- Tone: refined, courteous, rigorous and confident. Show competence through concrete, relevant evidence; no flattery, no filler, no clichés.
- Length: 170-230 words. Plain text only: no markdown, no placeholders, no square brackets.
- Structure: greeting; one-sentence purpose; two short paragraphs mapping the candidate's strongest evidence to the job's key requirements; a brief closing proposing a call; polite sign-off with the candidate's name.
- State that the candidate is available for fully remote work.
- Write in the language of the job posting (English if unclear).
- Return ONLY a JSON object: {"subject": string, "body": string}. The subject must be short and professional and include the job title.`;

return $input.all().map(it => {
  const j = it.json;
  const user = `CANDIDATE NAME: ${cfg.candidateName}\n\nCANDIDATE CV:\n"""\n${cv}\n"""\n\nJOB\nTitle: ${j.title}\nCompany: ${j.company || 'the hiring team'}\nURL: ${j.link}\nMatching strengths identified: ${(j.strengths || []).join('; ')}\nDescription:\n"""\n${j.description}\n"""\n\nReturn ONLY the JSON object.`;
  return { json: { ...j, geminiBody: {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: user }] }],
    generationConfig: { temperature: 0.4, maxOutputTokens: 4096, responseMimeType: 'application/json' }
  }}};
});

const cfg = $('Config').first().json;
const src = $('Build Letter Prompt').all();
const out = [];

$input.all().forEach((r, i) => {
  const idx = (r.pairedItem && r.pairedItem.item !== undefined) ? r.pairedItem.item : i;
  const s = src[idx];
  if (!s) return;
  const { geminiBody, ...job } = s.json;

  let letter = null;
  try {
    const t = (r.json && r.json.candidates && r.json.candidates[0] && r.json.candidates[0].content
      ? r.json.candidates[0].content.parts.map(p => p.text || '').join('') : '');
    letter = JSON.parse(t.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim());
  } catch (e) { letter = null; }

  const body = letter && letter.body ? String(letter.body).trim() : '';
  const subject = (letter && letter.subject) ? String(letter.subject).trim()
    : `Application - ${job.title} - ${cfg.candidateName}`;

  const signature = [
    '', '--',
    cfg.candidateName,
    [cfg.candidateEmail, cfg.candidatePhone].filter(Boolean).join(' | '),
    cfg.candidateLinkedIn ? 'LinkedIn: ' + cfg.candidateLinkedIn : '',
    cfg.cvLink ? 'CV: ' + cfg.cvLink : ''
  ].filter(x => x !== '').join('\n');

  const emailBody = body ? body + '\n' + signature : '';
  const dry = cfg.dryRun === true || cfg.dryRun === 'true';
  const emailReady = !!job.contactEmail && !!body && !dry;

  let manualReason = '';
  if (!job.contactEmail) manualReason = 'لا يوجد بريد إلكتروني للجهة في الإعلان — قدّم يدوياً عبر الرابط';
  else if (!body) manualReason = 'تعذّر توليد رسالة التقديم';
  else if (dry) manualReason = 'وضع التجربة (dryRun) مفعّل — لم يُرسل أي بريد';

  out.push({ json: { ...job, subject, emailBody, emailReady, manualReason } });
});
return out;

const d = $('Prepare Email').item.json;
const gm = $json || {};
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n - 1) + '…' : s; };

let status;
if (d.emailReady) {
  status = (gm.id && !gm.error) ? '✅ تم إرسال التقديم عبر Gmail' : '❌ فشل إرسال البريد — قدّم يدوياً';
} else {
  status = '📝 تقديم يدوي مطلوب: ' + d.manualReason;
}

const lines = [
  status, '',
  '💼 <b>' + esc(cut(d.title, 160)) + '</b>',
  d.company ? '🏢 ' + esc(cut(d.company, 80)) : '',
  '🌐 المصدر: ' + esc(d.source),
  '🎯 نسبة التوافق: <b>' + d.matchScore + '%</b> | الجودة: ' + d.qualityScore + ' | التقييم النهائي: ' + d.finalScore,
  '🔗 ' + esc(d.link),
  d.contactEmail ? '📧 ' + esc(d.contactEmail) : '📧 لا يوجد بريد',
  '', '📝 ' + esc(cut(d.summaryAr, 500)),
  (d.strengths && d.strengths.length) ? '✔️ نقاط القوة: ' + esc(cut(d.strengths.join('، '), 350)) : '',
  (d.missing && d.missing.length) ? '⚠️ نواقص: ' + esc(cut(d.missing.join('، '), 250)) : ''
].filter(x => x !== '');

if (d.emailBody) {
  lines.push('', '✉️ <b>الموضوع:</b> ' + esc(cut(d.subject, 150)), '<pre>' + esc(cut(d.emailBody, 1800)) + '</pre>');
}
return { json: { telegramText: lines.join('\n').slice(0, 4000) } };

const e = $json || {};
const err = (e.execution && e.execution.error) || {};
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const text = [
  '🚨 <b>فشل في Workflow التقديم الآلي</b>',
  'Workflow: ' + esc(e.workflow && e.workflow.name),
  'العقدة: ' + esc(err.node && err.node.name),
  'الرسالة: ' + esc(String(err.message || 'unknown').slice(0, 600)),
  e.execution && e.execution.url ? 'التنفيذ: ' + esc(e.execution.url) : ''
].filter(Boolean).join('\n');
return { json: { text } };
